def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_space = bins - item
    target_fraction = 1 / 3
    target_remaining = bins * target_fraction
    priority_scores = 1 / (1 + np.abs(remaining_space - target_remaining))
    return np.where(remaining_space >= 0, priority_scores, -np.inf)

